-- Worker-only fixed projections. Only approved queued jobs and their current original requester have scope.
CREATE VIEW privacy_source_scope AS SELECT j.id AS job_id,j.case_id,j.organization_id,j.country,j.requester_id,o.type,b.role AS requester_role,
 current_setting('narudzbine.privacy_snapshot_at')::timestamptz AS snapshot_at
 FROM privacy_export_job j JOIN organization o ON o.id=j.organization_id AND o.country=j.country
 JOIN business_account b ON b.id=j.requester_id AND b.organization_id=o.id JOIN account_identity a ON a.id=b.id
 WHERE j.state='QUEUED' AND o.state='ACTIVE' AND b.role IN('OWNER','ADMIN') AND a.state='ACTIVE' AND a.email_verified AND NOT a.credential_operation_pending;
CREATE VIEW privacy_source_requester AS SELECT j.job_id,a.id AS "id",a.email AS "email",a.display_name AS "displayName",b.role AS "role",a.state AS "state",a.language_override AS "languageOverride",b.home_location_id AS "homeLocationId",a.created_at AS "createdAt",a.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN account_identity a ON a.id=j.requester_id JOIN business_account b ON b.id=a.id AND a.id=j.requester_id;
CREATE VIEW privacy_source_organization AS SELECT j.job_id,o.id AS "id",o.type AS "type",o.country AS "country",o.currency AS "currency",o.display_name AS "displayName",o.legal_name AS "legalName",o.registration_identifier AS "registrationIdentifier",o.tax_identifier AS "taxIdentifier",o.address_line1 AS "addressLine1",o.address_line2 AS "addressLine2",o.address_city AS "city",o.address_postal_code AS "postalCode",o.address_latitude AS "latitude",o.address_longitude AS "longitude",o.default_language AS "defaultLanguage",o.state AS "state",o.staff_submission_restricted AS "staffSubmissionRestricted",o.partner_contact_id AS "partnerContactId",o.owner_account_id AS "ownerAccountId",o.created_at AS "createdAt",o.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN organization o ON o.id=j.organization_id;
CREATE VIEW privacy_source_members AS SELECT j.job_id,a.id AS "id",a.email AS "email",a.display_name AS "displayName",b.role AS "role",a.state AS "state",a.language_override AS "languageOverride",b.home_location_id AS "homeLocationId",a.created_at AS "createdAt",a.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN business_account b ON b.organization_id=j.organization_id JOIN account_identity a ON a.id=b.id;
CREATE VIEW privacy_source_locations AS SELECT j.job_id,l.id AS "id",l.revision AS "revision",l.name AS "name",l.address_line1 AS "addressLine1",l.address_line2 AS "addressLine2",l.address_city AS "city",l.address_postal_code AS "postalCode",l.country AS "country",l.address_latitude AS "latitude",l.address_longitude AS "longitude",l.contact_name AS "contactName",l.contact_phone AS "contactPhone",l.contact_email AS "contactEmail",l.instructions AS "instructions",l.state AS "state",l.created_at AS "createdAt",l.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN organization_location l ON l.organization_id=j.organization_id AND l.country=j.country;
CREATE VIEW privacy_source_contacts AS SELECT j.job_id,c.id AS "id",c.revision AS "revision",c.label AS "label",c.contact_name AS "name",c.contact_phone AS "phone",c.contact_email AS "email",c.state AS "state",c.created_at AS "createdAt",c.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN business_contact c ON c.organization_id=j.organization_id;
CREATE VIEW privacy_source_connections AS SELECT j.job_id,c.id AS "id",c.vendor_id AS "vendorId",c.buyer_id AS "buyerId",c.state AS "state",c.disconnected_reason AS "disconnectedReason",c.agreed_price_confirmation_required AS "agreedPriceConfirmationRequired",c.created_at AS "createdAt",c.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN trading_relationship c ON(c.vendor_id=j.organization_id OR c.buyer_id=j.organization_id) AND c.country=j.country;
CREATE VIEW privacy_source_plan AS SELECT j.job_id,p.id AS "id",a.revision AS "assignmentRevision",p.code AS "code",p.revision AS "planRevision",p.product_limit AS "productLimit",p.active_buyer_limit AS "activeBuyerLimit",p.retired AS "retired" FROM privacy_source_scope j JOIN organization_plan a ON a.organization_id=j.organization_id JOIN plan_revision p ON p.id=a.plan_revision_id;
CREATE VIEW privacy_source_plan_requests AS SELECT j.job_id,p.id AS "id",p.requested_plan_revision_id AS "requestedPlanRevisionId",p.revision AS "revision",p.state AS "state",p.resolution_reason AS "resolutionReason",p.created_at AS "createdAt",p.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN plan_change_request p ON p.vendor_id=j.organization_id;
CREATE VIEW privacy_source_invitations AS SELECT j.job_id,i.id AS "id",i.revision AS "revision",CASE WHEN i.purpose='TRADING' THEN 'TRADING' WHEN i.purpose='MEMBER' THEN 'MEMBER' ELSE 'SETUP_'||i.type END AS "purpose",i.recipient_email AS "recipientEmail",CASE WHEN i.purpose='MEMBER' THEN i.organization_id WHEN i.purpose='TRADING' THEN i.buyer_id ELSE(SELECT organization_id FROM setup_intent WHERE invitation_id=i.id AND state='COMPLETED') END AS "targetOrganizationId",CASE WHEN i.state='PENDING' AND i.expires_at<=j.snapshot_at THEN 'EXPIRED' ELSE i.state END AS "state",CASE WHEN COALESCE((SELECT e.state FROM setup_delivery d LEFT JOIN external_job e ON e.source_kind='SETUP' AND e.source_id=d.id WHERE d.invitation_id=i.id AND d.generation=i.generation AND d.proof_id IS NULL ORDER BY d.created_at DESC,d.id LIMIT 1),'QUEUED') IN('SUPPRESSED','EXPIRED') THEN 'FAILED' ELSE COALESCE((SELECT e.state FROM setup_delivery d LEFT JOIN external_job e ON e.source_kind='SETUP' AND e.source_id=d.id WHERE d.invitation_id=i.id AND d.generation=i.generation AND d.proof_id IS NULL ORDER BY d.created_at DESC,d.id LIMIT 1),'QUEUED') END AS "deliveryState",i.expires_at AS "expiresAt",i.created_at AS "createdAt",i.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN setup_invitation i ON i.country=j.country AND((i.purpose IN('MEMBER','BUYER_SETUP','TRADING') AND i.organization_id=j.organization_id) OR(i.purpose='TRADING' AND i.buyer_id=j.organization_id));
CREATE VIEW privacy_source_ownership_transfers AS SELECT j.job_id,t.id AS "id",t.issuer_id AS "issuerId",t.recipient_id AS "recipientId",(t.revision+CASE WHEN (CASE WHEN t.state='PENDING' AND t.expires_at<=j.snapshot_at THEN 'EXPIRED' WHEN t.state='PENDING' AND(t.issuer_id<>o.owner_account_id OR t.recipient_epoch<>a.security_epoch OR a.state<>'ACTIVE' OR NOT a.email_verified) THEN 'INVALIDATED' ELSE t.state END)<>t.state THEN 1 ELSE 0 END) AS "revision",CASE WHEN t.state='PENDING' AND t.expires_at<=j.snapshot_at THEN 'EXPIRED' WHEN t.state='PENDING' AND(t.issuer_id<>o.owner_account_id OR t.recipient_epoch<>a.security_epoch OR a.state<>'ACTIVE' OR NOT a.email_verified) THEN 'INVALIDATED' ELSE t.state END AS "state",t.expires_at AS "expiresAt",t.created_at AS "createdAt",t.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN ownership_transfer t ON t.organization_id=j.organization_id AND(j.requester_role='OWNER' OR t.recipient_id=j.requester_id) JOIN organization o ON o.id=t.organization_id JOIN account_identity a ON a.id=t.recipient_id;
CREATE VIEW privacy_source_products AS SELECT j.job_id,p.id AS "id",p.revision AS "revision",p.sku AS "sku",p.name AS "name",p.description AS "description",i.unit_id AS "unitId",p.pack_description AS "packDescription",i.category_id AS "categoryId",ARRAY(SELECT taxonomy_id FROM catalogue_product_tag WHERE product_id=p.id ORDER BY taxonomy_id) AS "tagIds",ARRAY(SELECT asset_id FROM catalogue_product_gallery WHERE product_id=p.id ORDER BY position) AS "galleryAssetIds",p.minimum_quantity AS "minimumQuantity",p.quantity_step AS "quantityStep",p.featured AS "featured",p.unit_pack_frozen AS "unitAndPackFrozen",CASE WHEN i.archived THEN 'ARCHIVED' WHEN i.active THEN 'ACTIVE' ELSE 'INACTIVE' END AS "state",p.created_at AS "createdAt",p.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN catalogue_product p ON p.vendor_id=j.organization_id JOIN catalogue_product_identity i ON i.id=p.id;
CREATE VIEW privacy_source_sku_reservations AS SELECT j.job_id,r.product_id AS "productId",r.normalized_sku AS "normalizedSku",r.retired AS "retired" FROM privacy_source_scope j JOIN product_sku_reservation r ON r.vendor_id=j.organization_id;
CREATE VIEW privacy_source_taxonomy AS SELECT j.job_id,t.id AS "id",t.revision AS "revision",t.kind AS "kind",t.name AS "name",t.name_frozen AS "nameFrozen",t.deleted AS "deleted",t.created_at AS "createdAt",t.updated_at AS "updatedAt" FROM privacy_source_scope j JOIN catalogue_taxonomy t ON t.vendor_id=j.organization_id;
CREATE VIEW privacy_source_agreed_prices AS SELECT j.job_id,p.id AS "id",c.buyer_id AS "buyerId",p.product_id AS "productId",p.revision AS "revision",p.unit_price AS "unitPrice",p.removed AS "removed",p.confirmed_generation<>c.connection_generation AS "confirmationRequired",p.created_at AS "createdAt" FROM privacy_source_scope j JOIN agreed_price p ON true JOIN trading_relationship c ON c.id=p.relationship_id AND c.vendor_id=j.organization_id;
CREATE VIEW privacy_source_agreed_price_history AS SELECT j.job_id,h.price_id AS "priceId",h.revision AS "revision",h.actor_id AS "actorId",h.unit_price AS "unitPrice",h.removed AS "removed",h.occurred_at AS "occurredAt" FROM privacy_source_scope j JOIN agreed_price_history h ON true JOIN agreed_price p ON p.id=h.price_id JOIN trading_relationship c ON c.id=p.relationship_id AND c.vendor_id=j.organization_id;
CREATE VIEW privacy_source_inventory AS SELECT j.job_id,b.product_id AS "productId",b.revision AS "revision",b.available_count AS "availableCount",c.enabled AS "trackingEnabled",b.available_count IS NULL OR b.confirmed_epoch<>c.confirmation_epoch AS "confirmationRequired",b.credit_quantity AS "creditQuantity",1000000000-b.credit_quantity AS "maximumSettableCount" FROM privacy_source_scope j JOIN stock_balance b ON b.vendor_id=j.organization_id JOIN inventory_control c ON c.vendor_id=b.vendor_id;
CREATE VIEW privacy_source_stock_history AS SELECT j.job_id,e.id AS "id",e.product_id AS "productId",e.type AS "type",e.before_count AS "beforeCount",e.after_count AS "afterCount",e.delta AS "delta",e.reason AS "reason",CASE WHEN e.type='ORDER_DEDUCTED' THEN NULL ELSE e.actor_id END AS "actorId",e.order_id AS "orderId",e.created_at AS "createdAt" FROM privacy_source_scope j JOIN stock_event e ON e.vendor_id=j.organization_id;
CREATE VIEW privacy_source_favorites AS SELECT j.job_id,f.product_id AS "productId",f.vendor_id AS "vendorId",f.created_at AS "createdAt" FROM privacy_source_scope j JOIN buyer_favorite f ON f.buyer_id=j.organization_id;
CREATE VIEW privacy_source_draft_events AS SELECT j.job_id,e.id AS "id",e.draft_id AS "draftId",e.revision AS "revision",e.actor_id AS "actorId",e.action AS "action",e.created_at AS "createdAt" FROM privacy_source_scope j JOIN draft_event e ON e.buyer_id=j.organization_id;
CREATE VIEW privacy_source_order_stages AS SELECT j.job_id,s.id AS "id",s.revision AS "revision",s.name AS "name",s.state AS "state",s.position AS "position" FROM privacy_source_scope j JOIN order_stage s ON s.vendor_id=j.organization_id;
CREATE VIEW privacy_source_order_events AS SELECT j.job_id,e.id AS "id",e.order_id AS "orderId",e.revision AS "revision",e.state AS "state",coalesce(e.actor_organization_id,e.buyer_id) AS "actorOrganizationId",CASE WHEN coalesce(e.actor_organization_id,e.buyer_id)=j.organization_id THEN e.actor_id ELSE NULL END AS "actorId",CASE WHEN coalesce(e.actor_organization_id,e.buyer_id)=j.organization_id THEN e.actor_display_name ELSE NULL END AS "actorDisplayName",e.previous_state AS "previousState",e.reason AS "reason",e.cancellation_request_id AS "cancellationRequestId",e.cancellation_request_state AS "cancellationRequestState",e.stage_id AS "stageId",e.stage_name AS "stageName",e.previous_stage_id AS "previousStageId",e.previous_stage_name AS "previousStageName",e.stage_configuration_revision AS "stageConfigurationRevision",e.created_at AS "createdAt" FROM privacy_source_scope j JOIN purchase_order_event e ON(e.vendor_id=j.organization_id OR e.buyer_id=j.organization_id) JOIN purchase_order o ON o.id=e.order_id AND o.country=j.country;
CREATE VIEW privacy_source_cancellations AS SELECT j.job_id,r.id AS "id",r.order_id AS "orderId",r.reason AS "reason",coalesce(s.action,'PENDING') AS "state",s.reason AS "resolutionReason",r.created_at AS "createdAt",coalesce(s.created_at,r.created_at) AS "updatedAt" FROM privacy_source_scope j JOIN cancellation_request r ON(r.vendor_id=j.organization_id OR r.buyer_id=j.organization_id) JOIN purchase_order o ON o.id=r.order_id AND o.country=j.country LEFT JOIN cancellation_resolution s ON s.request_id=r.id;
CREATE VIEW privacy_source_messages AS SELECT j.job_id,m.id AS "id",m.order_id AS "orderId",m.author_organization_id AS "authorOrganizationId",CASE WHEN m.author_organization_id=j.organization_id THEN m.author_id ELSE NULL END AS "authorId",CASE WHEN m.author_organization_id=j.organization_id THEN m.author_display_name ELSE NULL END AS "authorDisplayName",m.text AS "text",m.created_at AS "createdAt" FROM privacy_source_scope j JOIN order_message m ON true JOIN purchase_order o ON o.id=m.order_id AND o.country=j.country AND(o.vendor_id=j.organization_id OR o.buyer_id=j.organization_id);
CREATE VIEW privacy_source_inbox AS SELECT j.job_id,n.id AS "id",n.event_key AS "event",n.order_id AS "orderId",n.organization_id AS "organizationId",n.text AS "text",n.read AS "read",n.created_at AS "createdAt" FROM privacy_source_scope j JOIN notification n ON n.recipient_account_id=j.requester_id AND n.created_at>j.snapshot_at-interval '90 days';

CREATE VIEW privacy_source_pricing AS SELECT j.job_id,p.product_id,p.revision,p.base_price,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('minimumQuantity',t.minimum_quantity,'unitPrice',t.unit_price) ORDER BY t.minimum_quantity) FROM product_volume_tier t WHERE t.product_id=p.product_id),'[]'::jsonb)::text AS tiers
 FROM privacy_source_scope j JOIN catalogue_product c ON c.vendor_id=j.organization_id JOIN product_pricing p ON p.product_id=c.id;
CREATE VIEW privacy_source_pricing_history AS SELECT j.job_id,h.product_id,h.revision,h.actor_id,h.base_price,h.tiers::text AS tiers,h.occurred_at
 FROM privacy_source_scope j JOIN catalogue_product c ON c.vendor_id=j.organization_id JOIN product_pricing_history h ON h.product_id=c.id;
CREATE VIEW privacy_source_promotions AS SELECT j.job_id,p.id,p.revision,p.definition::text,p.target_labels::text,p.stopped_at,p.archived,p.created_at,p.updated_at
 FROM privacy_source_scope j JOIN promotion p ON p.vendor_id=j.organization_id;
CREATE VIEW privacy_source_promotion_history AS SELECT j.job_id,h.promotion_id,h.revision,h.actor_id,h.snapshot::text,h.occurred_at
 FROM privacy_source_scope j JOIN promotion p ON p.vendor_id=j.organization_id JOIN promotion_history h ON h.promotion_id=p.id;
CREATE VIEW privacy_source_drafts AS SELECT j.job_id,d.id,d.vendor_id,d.revision,d.preparation::text,d.state,d.submitted_order_id,d.created_at,d.updated_at,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('productId',l.product_id,'quantity',l.quantity) ORDER BY l.position) FROM buyer_draft_line l WHERE l.draft_id=d.id),'[]'::jsonb)::text AS lines
 FROM privacy_source_scope j JOIN buyer_draft d ON d.buyer_id=j.organization_id;
CREATE VIEW privacy_source_orders AS SELECT j.job_id, o.id,coalesce(e.result,o.snapshot)::text AS snapshot,
 (SELECT s.name FROM order_stage s WHERE s.id=(coalesce(e.result,o.snapshot)->'stage'->>'id')::uuid) AS current_stage_name
 FROM privacy_source_scope j JOIN purchase_order o ON(o.buyer_id=j.organization_id OR o.vendor_id=j.organization_id) AND o.country=j.country
 LEFT JOIN LATERAL(SELECT result FROM purchase_order_event WHERE order_id=o.id ORDER BY revision DESC LIMIT 1)e ON true;
CREATE VIEW privacy_source_preferences AS SELECT j.job_id,j.requester_id AS account_id,
 COALESCE(p.revision,1) AS revision,a.language_override,k.event,COALESCE(v.in_app,true) AS in_app,COALESCE(v.email,false) AS email,COALESCE(v.push,false) AS push
 FROM privacy_source_scope j JOIN account_identity a ON a.id=j.requester_id
 CROSS JOIN(VALUES('ORDER_SUBMITTED'),('ORDER_STATUS_CHANGED'),('CANCELLATION_REQUESTED'),('CANCELLATION_RESOLVED'),('MESSAGE_CREATED'),('RELATIONSHIP_DISCONNECTED'))k(event)
 LEFT JOIN notification_preferences p ON p.account_id=j.requester_id LEFT JOIN notification_preference v ON v.account_id=j.requester_id AND v.event_key=k.event;
CREATE VIEW privacy_source_business_audit AS SELECT j.job_id,e.id,e.actor_id,e.action,e.resource_id,e.request_id,
 CASE WHEN e.action IN('TRADING_DISCONNECTED','ORDER_REJECTED','ORDER_CANCELLED','CANCELLATION_REQUESTED','CANCELLATION_APPROVED','CANCELLATION_REJECTED','CANCELLATION_WITHDRAWN','CANCELLATION_RESOLVED') THEN e.reason ELSE NULL END AS reason,
 ARRAY(SELECT DISTINCT f FROM unnest(e.changed_fields)f WHERE f~'^[A-Za-z][A-Za-z0-9_]{0,99}$' AND f!~*'credential|password|secret|token|proof|evidence|mailbox|session|security_?epoch' ORDER BY f LIMIT 100) AS changed_fields,e.occurred_at
 FROM privacy_source_scope j JOIN audit_event e ON e.organization_id=j.organization_id AND e.country=j.country AND e.actor_type='BUSINESS' AND e.occurred_at<=j.snapshot_at
 AND e.resource_type IN('PRIVACY_CASE','PRIVACY_EXPORT','ORGANIZATION','LOCATION','CONTACT','MEMBER','OWNERSHIP_TRANSFER','RELATIONSHIP','PLAN_REQUEST','VENDOR_PLAN','CATEGORY','TAG','UNIT','MEDIA_ASSET','PRODUCT','AGREED_PRICE','PROMOTION','TRACKING','RECONCILIATION','STOCK','PRODUCT_PRICING','ORDER_STAGE','ORDER','ORDER_MESSAGE','IMPORT','EXPORT') AND e.action IN('PRIVACY_CASE_REQUESTED','PRIVACY_EXPORT_DOWNLOADED','AGREED_PRICES_REVIEWED','AGREED_PRICE_CONFIRMED','AGREED_PRICE_REMOVED','AGREED_PRICE_SAVED','CANCELLATION_APPROVED','CANCELLATION_REJECTED','CANCELLATION_REQUESTED','CANCELLATION_RESOLVED','CANCELLATION_WITHDRAWN','CONTACT_ARCHIVED','CONTACT_CREATED','CONTACT_RESTORED','CONTACT_UPDATED','IMPORT_CONFIRMED','IMPORT_PREVIEWED','LOCATION_ARCHIVED','LOCATION_CREATED','LOCATION_RESTORED','LOCATION_UPDATED','MEMBER_DEACTIVATED','MEMBER_REACTIVATED','MEMBER_ROLE_CHANGED','MESSAGE_CREATED','ORDER_ACCEPTED','ORDER_CANCELLED','ORDER_DELIVERED','ORDER_DISPATCHED','ORDER_REJECTED','ORDER_STAGE_CHANGED','ORDER_SUBMITTED','ORGANIZATION_UPDATED','PLAN_APPROVED','PLAN_ASSIGNED','PLAN_REJECTED','PLAN_REQUESTED','PLAN_SUPERSEDED','PLAN_WITHDRAWN','PRICING_UPDATED','PRODUCT_ACTIVATED','PRODUCT_ARCHIVED','PRODUCT_CREATED','PRODUCT_DEACTIVATED','PRODUCT_RESTORED','PRODUCT_UPDATED','PROMOTION_ARCHIVED','PROMOTION_CREATED','PROMOTION_STOPPED','PROMOTION_UPDATED','RECONCILIATION_ACKNOWLEDGED','RECONCILIATION_APPLIED','RECONCILIATION_PREPARED','STAGES_REORDERED','STAGE_CREATED','STAGE_RENAMED','STAGE_RETIRED','STOCK_ADJUSTED','STOCK_CONFIRMED','STOCK_INITIALIZED','STOCK_SET','TAXONOMY_CREATED','TAXONOMY_DELETED','TAXONOMY_RENAMED','TRACKING_DISABLED','TRACKING_ENABLED','TRADING_ADMIN_CONNECTED','TRADING_CONNECTED','TRADING_DISCONNECTED','TRADING_RECONNECTED','TRANSFER_ACCEPTED','TRANSFER_EXPIRED','TRANSFER_INVALIDATED','TRANSFER_REQUESTED','TRANSFER_REVOKED','UPLOAD_QUARANTINED','UPLOAD_RESERVED','EXPORT_CREATED','EXPORT_DOWNLOADED');
CREATE VIEW privacy_source_product_history AS SELECT a.* FROM privacy_source_business_audit a JOIN audit_event e ON e.id=a.id WHERE e.resource_type='PRODUCT';


CREATE VIEW privacy_export_work AS SELECT id,case_id,organization_id,country,requester_id,created_at FROM privacy_export_job j WHERE state='QUEUED' AND NOT EXISTS(SELECT 1 FROM account_identity a WHERE a.id=j.requester_id AND a.credential_operation_pending);
CREATE FUNCTION lock_privacy_export(job_id uuid,at_time timestamptz)
RETURNS TABLE(result text,case_id uuid,organization_id uuid,country text,organization_type text)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE job public.privacy_export_job%ROWTYPE; org public.organization%ROWTYPE; member public.business_account%ROWTYPE; person public.account_identity%ROWTYPE;
BEGIN
 SELECT * INTO job FROM public.privacy_export_job WHERE id=job_id AND state='QUEUED';IF NOT FOUND THEN RETURN;END IF;
 SELECT * INTO STRICT org FROM public.organization WHERE id=job.organization_id FOR UPDATE;
 SELECT * INTO STRICT person FROM public.account_identity WHERE id=job.requester_id FOR SHARE;
 SELECT * INTO STRICT member FROM public.business_account WHERE id=job.requester_id FOR SHARE;
 SELECT * INTO job FROM public.privacy_export_job WHERE id=job_id AND state='QUEUED' FOR UPDATE SKIP LOCKED;IF NOT FOUND THEN RETURN;END IF;
 IF at_time>=job.created_at+interval '24 hours' THEN PERFORM public.expire_privacy_exports(job.case_id,at_time);RETURN QUERY SELECT 'EXPIRED',job.case_id,org.id,org.country::text,org.type::text;RETURN;END IF;
 RETURN QUERY SELECT CASE WHEN person.credential_operation_pending THEN 'DEFER' WHEN person.state='ACTIVE' AND person.email_verified AND org.state='ACTIVE' AND member.role IN('OWNER','ADMIN') AND member.organization_id=org.id AND org.country=job.country THEN 'VALID' ELSE 'REVOKED' END,job.case_id,org.id,org.country::text,org.type::text;
END $$;
REVOKE ALL ON FUNCTION lock_privacy_export(uuid,timestamptz) FROM PUBLIC;
CREATE FUNCTION fail_privacy_export(job_id uuid,code text,at_time timestamptz) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE affected integer;
BEGIN
 UPDATE public.privacy_export_job SET state='FAILED',revision=revision+1,updated_at=at_time,completed_at=at_time,failure_code=code WHERE id=job_id AND state='QUEUED';
 GET DIAGNOSTICS affected=ROW_COUNT;RETURN affected;
END $$;
REVOKE ALL ON FUNCTION fail_privacy_export(uuid,text,timestamptz) FROM PUBLIC;
CREATE FUNCTION publish_privacy_export(job_id uuid,ciphertext bytea,sha256 bytea,bytes integer,records integer,at_time timestamptz) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE job public.privacy_export_job%ROWTYPE; used bigint;
BEGIN
 SELECT * INTO job FROM public.privacy_export_job WHERE id=job_id AND state='QUEUED' FOR UPDATE;IF NOT FOUND THEN RETURN 'UNCHANGED';END IF;
 IF at_time>=job.created_at+interval '24 hours' THEN PERFORM public.expire_privacy_exports(job.case_id,at_time);RETURN 'EXPIRED';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('privacy-export/storage',0));
 SELECT coalesce(sum(octet_length(artifact)::bigint),0) INTO used FROM public.privacy_export_job WHERE artifact IS NOT NULL;
 IF used+octet_length(ciphertext)>134217728 THEN PERFORM public.fail_privacy_export(job_id,'PRIVACY_EXPORT_CAPACITY_REACHED',at_time);RETURN 'FAILED';END IF;
 UPDATE public.privacy_export_job SET state='READY',revision=revision+1,updated_at=at_time,completed_at=at_time,expires_at=at_time+interval '24 hours',artifact=ciphertext,digest=sha256,byte_count=bytes,record_count=records WHERE id=job_id AND state='QUEUED';RETURN 'READY';
END $$;
REVOKE ALL ON FUNCTION publish_privacy_export(uuid,bytea,bytea,integer,integer,timestamptz) FROM PUBLIC;
CREATE FUNCTION sweep_privacy_exports(at_time timestamptz) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE selected record; affected integer:=0;
BEGIN
 FOR selected IN SELECT DISTINCT case_id FROM public.privacy_export_job WHERE(state='QUEUED' AND created_at+interval '24 hours'<=at_time) OR(state='READY' AND expires_at<=at_time) ORDER BY case_id LIMIT 25 LOOP
  affected:=affected+public.expire_privacy_exports(selected.case_id,at_time);
 END LOOP;
 IF NOT public.retention_preservation_active() THEN
  WITH due AS(SELECT id FROM public.privacy_export_job WHERE artifact_held ORDER BY id LIMIT 25 FOR UPDATE SKIP LOCKED)
  UPDATE public.privacy_export_job j SET artifact_held=false,artifact=NULL,digest=NULL,updated_at=greatest(j.updated_at,at_time) FROM due d WHERE j.id=d.id;
  WITH due AS(SELECT id FROM public.privacy_export_job WHERE original_response IS NOT NULL AND created_at+interval '168 hours'<=at_time ORDER BY created_at,id LIMIT 1000 FOR UPDATE SKIP LOCKED)
  UPDATE public.privacy_export_job j SET original_response=NULL,updated_at=greatest(j.updated_at,at_time) FROM due d WHERE j.id=d.id;
 END IF;
 RETURN affected;
END $$;
REVOKE ALL ON FUNCTION sweep_privacy_exports(timestamptz) FROM PUBLIC;



CREATE VIEW privacy_source_tracking AS SELECT j.job_id,c.vendor_id,c.revision,c.enabled FROM privacy_source_scope j JOIN inventory_control c ON c.vendor_id=j.organization_id;
CREATE VIEW privacy_source_partners AS
 SELECT j.job_id,o.id,o.display_name,o.legal_name,o.country,o.currency,o.registration_identifier,o.tax_identifier,c.contact_name,c.contact_phone,c.contact_email,r.id AS relationship_id,r.state AS relationship_state
 FROM privacy_source_scope j JOIN trading_relationship r ON(r.vendor_id=j.organization_id OR r.buyer_id=j.organization_id) AND r.country=j.country
 JOIN organization o ON o.id=CASE WHEN r.vendor_id=j.organization_id THEN r.buyer_id ELSE r.vendor_id END AND o.state='ACTIVE'
 LEFT JOIN business_contact c ON c.id=o.partner_contact_id AND c.organization_id=o.id AND c.state='ACTIVE' WHERE r.state='ACTIVE'
 UNION ALL
 SELECT j.job_id,s.organization_id,s.display_name,s.legal_name,s.country,s.currency,s.registration_identifier,s.tax_identifier,s.contact_name,s.contact_phone,s.contact_email,r.id,r.state
 FROM privacy_source_scope j JOIN trading_relationship r ON(r.vendor_id=j.organization_id OR r.buyer_id=j.organization_id) AND r.country=j.country
 JOIN partner_snapshot s ON s.relationship_id=r.id AND s.relationship_revision=r.revision AND s.organization_id=CASE WHEN r.vendor_id=j.organization_id THEN r.buyer_id ELSE r.vendor_id END WHERE r.state='DISCONNECTED';
UPDATE backend_schema_version SET version=72 WHERE id=1;
